-- NFT-коллекционка: 9 предметов по 8 вариантов. Тип kind = 'nft'.
do $$
declare r record;
begin
  for r in select conname, conrelid::regclass as tbl from pg_constraint
           where contype = 'c' and conrelid in ('public.catalog'::regclass, 'public.wallet_items'::regclass, 'public.case_items'::regclass)
             and pg_get_constraintdef(oid) like '%kind%' loop
    execute format('alter table %s drop constraint %I', r.tbl, r.conname);
  end loop;
end $$;
alter table public.catalog add constraint catalog_kind_check check (kind in ('theme','cloak','nft'));
alter table public.wallet_items add constraint wallet_items_kind_check check (kind in ('theme','cloak','nft'));
alter table public.case_items add constraint case_items_kind_check check (kind in ('theme','cloak','crystals','nft'));

create or replace function public._item_label(p_kind text, p_id text) returns text
language sql stable as $$
  select case p_kind
    when 'theme' then 'Тема: ' || coalesce((select name from public.catalog where kind = 'theme' and item_id = p_id), '?')
    when 'cloak' then 'Плащ: ' || coalesce((select name from public.catalog where kind = 'cloak' and item_id = p_id), '?')
    when 'nft' then 'NFT: ' || coalesce((select name from public.catalog where kind = 'nft' and item_id = p_id), '?')
    else case when p_id = '0' then 'Пусто' else p_id || ' кристалликов' end
  end
$$;

